#include <bits/stdc++.h>

#define all(a) a.begin(), a.end()
#define rall(a) a.rbegin(), a.rend()
#define len(a) (int)(a.size())

using namespace std;

using ll = long long;
using ld = long double;

const int N = 2228;

vector<int> G[N];
int tin[N], tout[N];
int timer = 0;
int cntup[N][N];
int cntdown[N][N];
ll ans1 = 0, ans2 = 0, ans3 = 0;

void solve_path(int n, int v, int d) {
    vector<int> dist(n);
    auto dfs = [&](auto &self, int v, int p, int h = 0) -> void {
        dist[v] = h;
        for (int i : G[v]) {
            if (i != p) self(self, i, v, h + 1);
        }
    };

    dfs(dfs, v, -1, 0);

    for (int i = v + 1; i < n; ++i) {
        if (dist[i] == d) {
            ans1 += d - 1;
        }
    }
}

void dfs_tin(int v, int p) {
    tin[v] = timer++;

    for (int i : G[v]) {
        if (i != p) dfs_tin(i, v);
    }
    tout[v] = timer;
}

void solve() {
    int n, d;
    cin >> n >> d;
    --d;
    for (int i = 0; i < n; ++i) G[i].clear();
    ans1 = 0, ans2 = 0, ans3 = 0, timer = 0;

    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        cin >> a >> b;
        G[a - 1].push_back(b - 1);
        G[b - 1].push_back(a - 1);
    }

    for (int i = 0; i < n; ++i) solve_path(n, i, d);
    for (int i = 0; i < n; ++i) {
        fill(cntup[i], cntup[i] + N, 0);
        fill(cntdown[i], cntdown[i] + N, 0);
    }
    dfs_tin(0, -1);

    for (int i = 0; i < n; ++i) {
        auto dfs = [&](auto &self, int v, int p, int h) -> void {
            if (tin[i] <= tin[v] && tin[v] < tout[i]) ++cntdown[i][h];
            else ++cntup[i][h];

            for (int j : G[v]) {
                if (j != p) self(self, j, v, h + 1);
            }
        };

        dfs(dfs, i, -1, 0);
    }

    vector<int> h(n);
    auto dfs = [&](auto &self, int v, int p, int hh = 0) -> vector<int> {
        int m = len(G[v]);
        vector<vector<int>> who(m);
        vector<int> all;
        all.push_back(v);
        h[v] = hh;

        for (int i = 0; i < len(G[v]); ++i) {
            if (G[v][i] == p) continue;

            who[i] = self(self, G[v][i], v, hh + 1);
            for (int j : who[i]) all.push_back(j);

            for (int j = 0; j < i; ++j) {
                for (int v1 : who[i]) {
                    for (int v2 : who[j]) {

                        int D = h[v1] + h[v2] - 2 * hh;
                        if (D >= d) continue;
                        int need = d - D;
                        ans2 += cntup[v][need];
                        int cnt3 = cntdown[v][need];
                        cnt3 -= cntdown[G[v][i]][need - 1];
                        cnt3 -= cntdown[G[v][j]][need - 1];
                        ans3 += cnt3;

                    }
                }
            }
        }

        return all;
    };

    dfs(dfs, 0, -1, 0);
    cout << ans1 + ans2 + ans3 / 3 << '\n';
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int t = 1;
    cin >> t;
    while (t--) solve();
}

#include <bits/stdc++.h>

