const char nl = '\n';
typedef long long ll;
typedef long double ld;

using namespace std;

const int K = 450;

void solve() {
    int n, q;
    cin >> n >> q;

    vector<int> f(n, -1); // f[i] = -1 if impossible, 1 if i = a^2, 2 if i = a^2 + b^2
    for (int a = 1; a * a < n; a++) {
        for (int b = a; a * a + b * b < n; b++) {
            f[a * a + b * b] = 2;
        }

        f[a * a] = 1;
    }

    vector<int> g(n, -1); // g[i] = -1 if impossible, else min `b` over i = a^2 - b^2
    for (int b = 1; b * b < n; b++) {
        for (int a = b; a * a - b * b < n; a++) {
            int v = a * a - b * b;
            if (g[v] < 0) g[v] = b * b;
        }
    }

    while (q--) {
        int a, b;
        cin >> a >> b;

        int ans = 4;
        for (int d = -K; d <= K; d++) {
            int x = a + abs(d) * d;
            if (x <= 0 || x > n) continue;

            int ta = x, tb = b;
            if (ta > tb) swap(ta, tb);

            int tans = 4;
            {
                int v = tb - ta;
                if (g[v] > 0 && g[v] <= max(n - tb, ta - 1)) {
                    tans = 2;
                }

                if (f[v] > 0) {
                    tans = f[v];
                }

                if (d != 0) tans++;
            }

            ans = min(ans, tans);
        }

        cout << ans << nl;
    }
}

int main() {
	ios::sync_with_stdio(0); cin.tie(0);

    int t;
    cin >> t;
    while (t--) solve();
}
